import{_ as t,a,o as r,a2 as n}from"./chunks/framework.DCcmcJcL.js";const c=JSON.parse('{"title":"Review Translation","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/review-translation.md","filePath":"generative-ai/review-translation.md","lastUpdated":1789441803000}'),o={name:"generative-ai/review-translation.md"};function s(i,e,l,h,p,d){return r(),a("div",null,e[0]||(e[0]=[n('<h1 id="review-translation" tabindex="-1">Review Translation <a class="header-anchor" href="#review-translation" aria-label="Permalink to &quot;Review Translation&quot;">​</a></h1><div class="feature-meta feature--ai"><span class="feature-meta__primary">Generative AI</span><span>Storefront</span></div><p>Review translation lets shoppers read a product review in their own language. A <strong>Translate</strong> button appears under each review on the product page. When a shopper clicks it, the model translates the review into the language they&#39;re browsing your store in. A review written in another language is still useful to them, and the review itself isn&#39;t changed.</p><h2 id="where-it-appears" tabindex="-1">Where it appears <a class="header-anchor" href="#where-it-appears" aria-label="Permalink to &quot;Where it appears&quot;">​</a></h2><p>The <strong>Translate</strong> button sits under the text of each approved review on a product page.</p><h2 id="translate-a-review" tabindex="-1">Translate a review <a class="header-anchor" href="#translate-a-review" aria-label="Permalink to &quot;Translate a review&quot;">​</a></h2><p>This is what a shopper does on the storefront:</p><ol><li>Open a product page and scroll to its reviews.</li><li>Under a review, click <strong>Translate</strong>. The button reads <strong>Translating...</strong> while the model works.</li></ol><p>The review&#39;s text is replaced on the shopper&#39;s screen by the translation, in the language currently selected in the storefront. The review title stays as it was written. When the shopper reloads the page, the original text is shown again. If the translation fails, the shopper sees an error message and the review stays as written.</p><h3 id="what-to-expect" tabindex="-1">What to expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to expect&quot;">​</a></h3><ul><li><strong>Translations go straight to the shopper, without your review.</strong> Try the feature on a few reviews before you switch it on for a channel.</li><li><strong>Each click is a new translation.</strong> Translations aren&#39;t stored. Every click on <strong>Translate</strong> sends the review to the provider again, and each one is a separate request that the provider bills.</li></ul><h2 id="what-you-control" tabindex="-1">What you control <a class="header-anchor" href="#what-you-control" aria-label="Permalink to &quot;What you control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong> under <strong>Configure &gt;&gt; Magic AI &gt;&gt; General</strong></td><td>Switches Magic AI on for your store</td></tr><tr><td><strong>Enabled</strong> in the <strong>Review Translation</strong> section of <strong>Configure &gt;&gt; Magic AI &gt;&gt; Storefront Features</strong></td><td>Shows the <strong>Translate</strong> button, per channel</td></tr><tr><td><strong>Model</strong> in the <strong>Review Translation</strong> section</td><td>The model that translates reviews, per channel</td></tr></tbody></table><p>Save the API key of the chosen model&#39;s provider under <strong>Configure &gt;&gt; Magic AI &gt;&gt; Providers</strong> first. To set everything up, see <a href="./../configure/magic-ai.html#enable-the-storefront-features">Enable the storefront features</a>.</p><p>Only reviews you&#39;ve approved appear on the storefront, so only approved reviews can be translated. See <a href="./../customer/customer-review.html#approve-or-disapprove-a-review">Approve or disapprove a review</a>.</p>',15)]))}const u=t(o,[["render",s]]);export{c as __pageData,u as default};
